-- InsertDataset.sql
-- Canonical seed for the ByteMePC.io part catalogue.
-- Generated by merging wholedatabase.sql (real prices, full table set)
-- with MRSCCS.sql (real image links + cooler_socket), joined by part name.
-- Idempotent: re-running upserts every row.

BEGIN;

-- CPU (50 rows)
ON CONFLICT ("cpu_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "core_numbers" = EXCLUDED."core_numbers", "frequency" = EXCLUDED."frequency", "socket" = EXCLUDED."socket", "price" = EXCLUDED."price";

-- MOTHERBOARD (50 rows)
ON CONFLICT ("mb_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "wifi" = EXCLUDED."wifi", "socket" = EXCLUDED."socket", "size" = EXCLUDED."size", "ram_slots" = EXCLUDED."ram_slots", "ram_type" = EXCLUDED."ram_type", "price" = EXCLUDED."price";

-- GPU (50 rows)
ON CONFLICT ("gpu_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "core_clock" = EXCLUDED."core_clock", "memory" = EXCLUDED."memory", "tdp" = EXCLUDED."tdp", "price" = EXCLUDED."price";

-- CPU_COOLER (50 rows)
ON CONFLICT ("cooler_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "type" = EXCLUDED."type", "tdp_rating" = EXCLUDED."tdp_rating", "price" = EXCLUDED."price";

-- PSU (50 rows)
ON CONFLICT ("psu_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "wattage" = EXCLUDED."wattage", "form_factor" = EXCLUDED."form_factor", "efficiency_rating" = EXCLUDED."efficiency_rating", "price" = EXCLUDED."price";

-- RAM (50 rows)
ON CONFLICT ("ram_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "type" = EXCLUDED."type", "capacity" = EXCLUDED."capacity", "speed" = EXCLUDED."speed", "price" = EXCLUDED."price";

-- STORAGE (50 rows)
ON CONFLICT ("storage_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "type" = EXCLUDED."type", "capacity" = EXCLUDED."capacity", "interface" = EXCLUDED."interface", "read_speed" = EXCLUDED."read_speed", "write_speed" = EXCLUDED."write_speed", "price" = EXCLUDED."price";

-- PC_CASE (50 rows)
ON CONFLICT ("case_id") DO UPDATE SET "name" = EXCLUDED."name", "brand" = EXCLUDED."brand", "image_link" = EXCLUDED."image_link", "price" = EXCLUDED."price";

-- COOLER_SOCKET (560 rows)
ON CONFLICT ("cooler_id", "socket") DO NOTHING;

-- PORT (10 rows) — lookup table, prerequisite for the port junctions
ON CONFLICT ("type") DO NOTHING;

-- CASE_SUPPORTED_SIZE (132 rows) — derived from case names
ON CONFLICT ("case_id", "size") DO NOTHING;

-- MOTHERBOARD_PORT (221 rows) — SYNTHETIC plausible rear I/O
ON CONFLICT ("mb_id", "port_type") DO UPDATE SET "quantity" = EXCLUDED."quantity";

-- GPU_PORT (100 rows) — SYNTHETIC plausible display outputs
ON CONFLICT ("gpu_id", "port_type") DO UPDATE SET "quantity" = EXCLUDED."quantity";

COMMIT;
